import tqdm

def process(paths, out):
    # check out each file, skip the ones already done
    with open(out, "a") as fh:
        for p in tqdm.tqdm(paths):
            try:
                data = p.read_text().splitlines()
                fh.write(data[0] + "\n")
            except IndexError:
                continue
            finally:
                fh.flush()
    return len(paths)
